#include <iostream>
using namespace std;
int main() {
    double pr, k;
    //pr - процент жирности;
    //k - количество литров;
    cout << "Введите процент жирности:";
    cin >> pr;
    cout << "Введите количество литров:";
    cin >> k;
    if ((pr >= 3.4) and (k >= 15))
    {
        cout << "Покупаем";
    }
    else
    {
        cout << "Не покупаем";
    }
}

#include <iostream>
using namespace std;
int main() {
    string a, b;
    //a - блок задач А;
    //b - блок задач В;
    cout << "Выполнил блок А: ";
    cin >> a;
    cout << "Выполнил блок В: ";
    cin >> b;
    if ((a == "да") or (b == "да"))
    { cout << "Домашняя работа выполнена"; }
    else
    { cout << "Надо сделать один из блоков"; }
}

int v; string p;
//v-возраст, p-племянник.
cout << "Введите возраст= ";
cin >> v;
cout << "Является племянником? (да/нет): ";
cin >> p;
if (v < 7 && p == "да")
    cout << "Подарок нужен";
else
    cout << "Подарок купят другие";

string r, d, k;
//r-разрешение, d-дом, k-кафе.
cout << "Родители разрешили? (да/нет): ";
cin >> r;
cout << "Праздник будет дома? (да/нет): ";
cin >> d;
cout << "Праздник будет в кафе? (да/нет): ";
cin >> k;
if (r == "да" && (d == "да" || k == "да"))
    { cout << "Праздник будет"; }
else
    { cout << "Праздника не будет"; }

int t;
cout << "Введите время t= ";
cin >> t;
if ((t >= 8 and t <= 12) or (t >= 14 and t <= 18) or (t >= 19 and t <= 20))
    { cout << "Спортзал работает"; }
else
    { cout << "Спортзал не работает"; }

int year;
cout << "Введите год: ";
cin >> year;
if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0)
    cout << year << " - високосный год!" << endl;
else
    cout << year << " - не високосный год." << endl;

